def longestNonOverlappingRepeat(s):
    MOD = (1 << 61) - 1
    B = 911382323
    n = len(s)
    H = [0] * (n + 1)
    PW = [1] * (n + 1)
    for i, c in enumerate(s):
        H[i + 1] = (H[i] * B + ord(c)) % MOD
        PW[i + 1] = PW[i] * B % MOD

    def feasible(L):
        first = {}
        for j in range(n - L + 1):
            h = (H[j + L] - H[j] * PW[L]) % MOD
            i = first.setdefault(h, j)
            if j - i >= L:
                return True
        return False

    lo, hi = 0, n // 2
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if feasible(mid):
            lo = mid
        else:
            hi = mid - 1
    return lo
